def matrix_with_k_fixed_elements_exists(n: int, k: int) -> bool:
    """Given n and k, decide whether an n by n binary matrix can have exactly
    k entries whose values are determined by its row and column sums.
    """
    if not 2 <= n <= 30 or not 0 <= k <= n * n:
        return False
    if k == 0 or k == n * n:
        return True

    # A nontrivial fiber of binary matrices contains an alternating cycle,
    # so counts very close to n^2 cannot occur.
    if k < n or k > n * n - 4:
        return False

    # Small exceptional gaps in the attainable counts.
    impossible = {
        2: {2, 3},
        3: {6, 7},
        4: {5, 8, 13, 14},
        5: {24},
        18: {14, 15, 26, 42},
        27: {106},
        29: {18, 123, 186},
    }
    return k not in impossible.get(n, set())
